-- Hospital database seed with synthetic demo values filled for previously blank fields.
-- IMPORTANT: Synthetic values are explicitly labeled data_status=synthetic_demo_data and verification_status=simulated.
CREATE TABLE IF NOT EXISTS public.hospitals (
  hospital_id text NOT NULL, name text NOT NULL, city text, state text, pincode text, address text NOT NULL,
  latitude double precision, longitude double precision, specialties text[] NOT NULL DEFAULT '{}'::text[],
  procedures text[] NOT NULL DEFAULT '{}'::text[], cost_min integer, cost_max integer, currency text NOT NULL DEFAULT 'INR',
  facilities text[] NOT NULL DEFAULT '{}'::text[], accreditation text[] NOT NULL DEFAULT '{}'::text[], pmjay_empanelled boolean NOT NULL DEFAULT false,
  annual_procedure_volume integer, outcome_metric text, icu_beds integer,
  source_type text NOT NULL CHECK (source_type = ANY (ARRAY['official','public','synthetic'])),
  verification_status text NOT NULL CHECK (verification_status = ANY (ARRAY['verified','pending','simulated'])),
  source_url text, last_verified date, last_updated date NOT NULL, data_status text NOT NULL DEFAULT 'synthetic_demo_data',
  condition_tag text, review_status text NOT NULL DEFAULT 'approved' CHECK (review_status = ANY (ARRAY['pending','approved','rejected'])),
  phone text, facility_type text, date_of_establishment text, success_rates jsonb NOT NULL DEFAULT '{}'::jsonb,
  CONSTRAINT hospitals_pkey PRIMARY KEY (hospital_id)
);

ON CONFLICT (hospital_id) DO UPDATE SET
  name=EXCLUDED.name,
  city=EXCLUDED.city,
  state=EXCLUDED.state,
  pincode=EXCLUDED.pincode,
  address=EXCLUDED.address,
  latitude=EXCLUDED.latitude,
  longitude=EXCLUDED.longitude,
  specialties=EXCLUDED.specialties,
  procedures=EXCLUDED.procedures,
  cost_min=EXCLUDED.cost_min,
  cost_max=EXCLUDED.cost_max,
  currency=EXCLUDED.currency,
  facilities=EXCLUDED.facilities,
  accreditation=EXCLUDED.accreditation,
  pmjay_empanelled=EXCLUDED.pmjay_empanelled,
  annual_procedure_volume=EXCLUDED.annual_procedure_volume,
  outcome_metric=EXCLUDED.outcome_metric,
  icu_beds=EXCLUDED.icu_beds,
  source_type=EXCLUDED.source_type,
  verification_status=EXCLUDED.verification_status,
  source_url=EXCLUDED.source_url,
  last_verified=EXCLUDED.last_verified,
  last_updated=EXCLUDED.last_updated,
  data_status=EXCLUDED.data_status,
  condition_tag=EXCLUDED.condition_tag,
  review_status=EXCLUDED.review_status,
